        <el-descriptions :column="2" border><el-descriptions-item label="负责人">{{ ownerName(selected.business_profile?.profile.owner_user_id) }}</el-descriptions-item><el-descriptions-item label="授权范围">{{ selected.business_profile?.profile.scope_kind === 'ENTERPRISE' ? '当前企业' : selected.business_profile ? '指定项目' : '尚未登记' }}</el-descriptions-item><el-descriptions-item label="连接状态">{{ stateLabels[selected.state] }}</el-descriptions-item><el-descriptions-item label="配置有效期">{{ time(selected.definition.expires_at) }}</el-descriptions-item><el-descriptions-item label="最近验证">{{ time(selected.last_verification?.updated_at) }}</el-descriptions-item><el-descriptions-item label="最近同步">{{ time(selected.last_sync?.updated_at) }}</el-descriptions-item></el-descriptions>
