          <el-tab-pane label="审核记录" name="DECIDE" /><el-tab-pane label="验证记录" name="VERIFY" /><el-tab-pane label="同步记录" name="SYNC" />
        </el-tabs>
        <template v-if="detailTab !== 'configuration'"><el-button :disabled="busy" :loading="historyLoading" @click="loadHistory(null)">读取处理记录</el-button><el-table v-if="history" :data="history.items" empty-text="当前配置没有对应处理记录"><el-table-column label="时间" min-width="160"><template #default="{row}">{{ time(row.created_at) }}</template></el-table-column><el-table-column label="人员" min-width="130"><template #default="{row}">{{ ownerName(row.actor_id) }}</template></el-table-column><el-table-column label="处理状态" min-width="140"><template #default="{row}">{{ approvalLabels[row.state as keyof typeof approvalLabels] ?? row.state }}</template></el-table-column><el-table-column label="决定依据 / 运行结果" min-width="200"><template #default="{row}">{{ row.request.reason ?? row.run?.failure ?? (row.run ? '读取实际运行记录' : '已记录') }}<el-button v-if="row.run" link type="primary" @click="run = row.run">查看运行详情</el-button></template></el-table-column></el-table><el-button v-if="history?.next_after" :disabled="busy" @click="loadHistory(history.next_after)">加载更多处理记录</el-button></template>
