        <section v-if="run" class="run-result"><h3>实际运行结果</h3><p>{{ run.state }} {{ run.failure }}</p><p>资料项目数量：{{ run.items.length }}；资料权利仍需人工核查。</p><el-table :data="run.items" empty-text="本次运行没有取得资料项目"><el-table-column prop="item_id" label="资料项目标识" min-width="260" /><el-table-column prop="state" label="处理状态" /></el-table><el-collapse><el-collapse-item title="原始回执与摘要" name="run"><pre>{{ JSON.stringify(run,null,2) }}</pre></el-collapse-item></el-collapse></section>
      </template>
    </el-drawer>
    <el-dialog v-model="serviceOpen" :title="serviceCategory === 'identity' ? '账号与单点登录' : '专家服务协作'" width="min(94vw,640px)" append-to-body>
      <template v-if="serviceCategory === 'identity'"><el-descriptions :column="1" border><el-descriptions-item label="当前身份接入">{{ workspace?.identity_mode === 'local' ? '企业本地账号' : '企业单点登录 OIDC' }}</el-descriptions-item><el-descriptions-item label="角色与会话">使用当前企业成员授权及服务端会话策略</el-descriptions-item></el-descriptions><p>身份提供方配置与账号映射需要经过部署配置和授权核查。切换页面选项不会修改实际登录方式。</p><div class="action-row"><router-link to="/account"><el-button>本人账户</el-button></router-link><router-link to="/enterprises/members"><el-button>成员与权限</el-button></router-link><router-link to="/enterprises/roles"><el-button>企业岗位</el-button></router-link></div></template>
      <template v-else><p>服务项目、专家范围、交付文档与验收需要明确业务资料和有效成员授权。</p><p>专家访问范围由项目与资料权限分别控制，结束协作后需要撤销对应授权。</p><div class="action-row"><router-link to="/projects"><el-button>服务项目</el-button></router-link><router-link to="/enterprises/members"><el-button>专家成员与权限</el-button></router-link></div></template>
    </el-dialog>
  </main>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, ref, shallowRef, watch } from 'vue'
import { Connection, User, Service } from '@element-plus/icons-vue'
import useUserStore from '@/store/modules/user'
import ProjectScopeSelect from '@/components/Medical/ProjectScopeSelect.vue'
import ConnectorConfigurationForm from './connector-configuration-form.vue'
import { useMedicalRouteRead } from '@/api/medical/route-read'
import { listProjects } from '@/api/medical/projects'
import { fail } from '@/api/medical/protocol'
import type { Member } from '@/api/medical/protocol'
import { activeMember, memberLabelName, memberLabelsAllowed, readMemberLabels } from '@/api/medical/member-labels'
import type { MemberLabel } from '@/api/medical/member-labels'
import { clearConnectorPending, connectorAllowed, lookupConnectorWrite, prepareConnectorWrite, readConnectorConfiguration, readConnectorDirectory, readConnectorHistory, readConnectorPending, readConnectorWorkspace, submitConnectorWrite } from '@/api/medical/customer-connectors'
import type { ConnectorConfiguration, ConnectorCreate, ConnectorDirectoryEntry, ConnectorHistory, ConnectorOperation, ConnectorPending, ConnectorRun, ConnectorWorkspace } from '@/api/medical/customer-connectors'
const user=useUserStore(),deployment=ref('private'),workspace=shallowRef<ConnectorWorkspace|null>(null),loading=ref(false),directoryLoading=ref(false),historyLoading=ref(false)
const projectId=ref(''),projectNames=ref<Record<string,string>>({}),entries=shallowRef<ConnectorDirectoryEntry[]>([]),nextAfter=ref<string|null>(null),directoryRead=ref(false)
const members=shallowRef<MemberLabel[]>([]),membersAfter=ref<string|null>(null),pending=shallowRef<ConnectorPending|null>(null),pendingBody=shallowRef<unknown>(null),pendingState=ref(''),restoreReason=ref('')
const editOpen=ref(false),editSource=shallowRef<ConnectorConfiguration|null>(null),editHead=ref('0'),formKey=ref(0),detailOpen=ref(false),selected=shallowRef<ConnectorConfiguration|null>(null),detailTab=ref('configuration'),reason=ref(''),maximumItems=ref(25),run=shallowRef<ConnectorRun|null>(null),history=shallowRef<ConnectorHistory|null>(null)
const serviceOpen=ref(false),serviceCategory=ref('identity'),controller=shallowRef(new AbortController());let generation=0
const categories=[{id:'identity',name:'账号与单点登录',description:'身份提供方、角色映射与会话策略',icon:User},{id:'documents',name:'资料系统连接',description:'文件同步、版本、访问权限与更新策略',icon:Connection},{id:'service',name:'专家服务协作',description:'服务项目、专家范围、交付文档与验收',icon:Service}]
const deploymentCopy:Record<string,string>={private:'私有化部署使用企业批准的服务与数据边界，接入条件由实际配置核验。',saas:'SaaS 企业空间按工作组织隔离数据，企业与项目权限分别核验。',service:'配套服务通过指定项目开展协作，专家读取与交付范围需要明确授权。'}
const approvalLabels={DRAFT:'待审核',APPROVED:'已批准',REVOKED:'已撤销'},stateLabels={BLOCKED:'接入条件未满足',READY_FOR_VERIFICATION:'等待真实验证',VERIFIED:'最近验证通过'},operationLabels={CREATE:'保存配置',DECIDE:'人工审核',VERIFY:'连接验证',SYNC:'资料同步'}
const blockerLabels:Record<string,string>={interface_spec:'缺少客户接口规格',account_mapping:'缺少客户账号映射',ownership_scope:'缺少资料归属及同步范围',credential_reference_id:'缺少受控凭据引用',credential_revision:'缺少受控凭据版本',CONFIGURATION_NOT_APPROVED:'当前配置尚未批准',CUSTOMER_PROTOCOL_ADAPTER_MISSING:'客户协议适配器尚未配置',APPROVED_CREDENTIAL_DIRECTORY_MISSING:'受控凭据目录尚未配置',BUSINESS_PROFILE_OWNER_INACTIVE:'负责人当前成员资格无效',CURRENT_APPROVAL_OR_MAPPING_NOT_VALID:'当前批准或账号映射未通过核验',CURRENT_CREDENTIAL_BINDING_NOT_VALID:'当前受控凭据绑定无效'}
function clear(){generation++;controller.value.abort();controller.value=new AbortController();workspace.value=null;loading.value=false;directoryLoading.value=false;historyLoading.value=false;entries.value=[];nextAfter.value=null;directoryRead.value=false;members.value=[];membersAfter.value=null;pending.value=null;pendingBody.value=null;pendingState.value='';editOpen.value=false;editSource.value=null;detailOpen.value=false;selected.value=null;history.value=null;run.value=null;reason.value='';serviceOpen.value=false;projectNames.value={}}
const active=useMedicalRouteRead('MedicalConnections',clear),busy=computed(()=>user.medicalWriting||loading.value||directoryLoading.value||historyLoading.value),projectName=computed(()=>projectNames.value[projectId.value]??projectId.value)
const activeMembers=computed(()=>members.value.filter(activeMember)),approvalBlockers=computed(()=>selected.value?.blockers.filter(value=>value!=='CONFIGURATION_NOT_APPROVED')??[])
function can(action:Parameters<typeof connectorAllowed>[1]){return active.value&&connectorAllowed(user.medicalSession,action)&&!!workspace.value?.allowed_actions.includes(action)}
function time(value:string|undefined){return value?new Date(value).toLocaleString('zh-CN',{hour12:false}):'暂无实际记录'}
function configName(value:ConnectorConfiguration){return value.business_profile?.profile.name??'尚未登记业务名称的连接'}
function ownerName(id:string|undefined){if(!id)return '尚未登记';const member=members.value.find(value=>value.user_id===id);return member?memberLabelName(member):id===user.medicalSession?.user.user_id?user.medicalSession.user.display_name??user.medicalSession.user.username??'当前成员':'成员姓名尚未读取'}
async function loadMembers(after:string|null){const session=user.medicalSession;if(!session||!memberLabelsAllowed(session))return;const current=generation,value=await readMemberLabels(session,after,controller.value.signal);if(current!==generation||!active.value||user.medicalSession!==session)return;members.value=after?[...members.value,...value.items]:value.items;membersAfter.value=value.next_after}
async function refresh(){const session=user.medicalSession;if(!active.value||!session||busy.value)return;const current=generation;loading.value=true;try{const value=await readConnectorWorkspace(session,controller.value.signal);if(current!==generation||!active.value||user.medicalSession!==session)return;workspace.value=value;pending.value=readConnectorPending(session);await loadMembers(null);if(!memberLabelsAllowed(session)){const self=session.user,member=session.memberships.find((item:Member)=>item.tenant_id===session.current_context?.tenant_id);if(!member||member.status!=='ACTIVE')fail('ACCESS_DENIED','当前组织成员资格无效');members.value=[{user_id:self.user_id,display_name:self.display_name,username:self.username,member_status:member.status,valid_from:member.valid_from,valid_to:member.valid_to}]}const projects=await listProjects(session.current_context!,{},controller.value.signal);if(current!==generation||user.medicalSession!==session||!active.value)return;projectNames.value=Object.fromEntries(projects.projects.map(item=>[item.project_id,item.name]));if(!projectId.value&&projects.projects.length===1&&!projects.next_after)projectId.value=projects.projects[0]!.project_id;if(projectId.value&&can('connector.read'))await loadDirectory(null)}finally{if(current===generation)loading.value=false}}
async function loadDirectory(after:string|null){const session=user.medicalSession;if(!session||!can('connector.read')||!projectId.value||directoryLoading.value)return;const current=generation,project=projectId.value;directoryLoading.value=true;try{const value=await readConnectorDirectory(session,project,after,controller.value.signal);if(current!==generation||projectId.value!==project||user.medicalSession!==session||!active.value)return;if(after&&value.items.some(item=>entries.value.some(existing=>existing.connector_id===item.connector_id)))fail('CONTENT_MISMATCH','连接目录分页包含重复项目');entries.value=after?[...entries.value,...value.items]:value.items;nextAfter.value=value.next_after;directoryRead.value=true}finally{if(current===generation)directoryLoading.value=false}}
function manage(id:string){if(id==='documents'){document.querySelector('.connector-directory')?.scrollIntoView({behavior:'smooth',block:'start'});return}serviceCategory.value=id;serviceOpen.value=true}
function create(entry:ConnectorDirectoryEntry|null){if(!projectId.value||!can('connector.configure')||busy.value||pending.value)return;editSource.value=entry?.configuration??null;editHead.value=entry?.head_revision??'0';formKey.value++;editOpen.value=true}
function restoreCreate(){if(!pending.value||pending.value.kind!=='CREATE')return;projectId.value=pending.value.project_id;editSource.value=null;editHead.value=pending.value.create_identity?.expected_revision??'0';formKey.value++;editOpen.value=true}
function open(value:ConnectorConfiguration){selected.value=value;detailOpen.value=true;detailTab.value='configuration';reason.value='';run.value=null;history.value=null}
async function reloadSelected(){const session=user.medicalSession,value=selected.value;if(!session||!value||busy.value)return;const current=generation,result=await readConnectorConfiguration(session,value.config_revision,controller.value.signal);if(current===generation&&user.medicalSession===session&&active.value)selected.value=result}
async function loadHistory(after:string|null){const session=user.medicalSession,value=selected.value,kind=detailTab.value as ConnectorHistory['kind'];if(!session||!value||!['DECIDE','VERIFY','SYNC'].includes(kind)||historyLoading.value)return;const current=generation;historyLoading.value=true;try{const result=await readConnectorHistory(session,value.config_revision,kind,after,controller.value.signal);if(current!==generation||user.medicalSession!==session||selected.value?.config_revision!==value.config_revision||detailTab.value!==kind||!active.value)return;history.value=after&&history.value?{...result,items:[...history.value.items,...result.items]}:result}finally{if(current===generation)historyLoading.value=false}}
async function resolvePending(){const session=user.medicalSession,original=pending.value;if(!session||!original)return;const result=await lookupConnectorWrite(session,original,controller.value.signal);if(user.medicalSession!==session||!active.value)return;if(result.configuration)selected.value=result.configuration;if(result.run)run.value=result.run;if(result.state==='COMPLETED'){clearConnectorPending(session,original);pending.value=null;pendingBody.value=null;pendingState.value='原请求已核清，持久记录与完整参数摘要一致。';}else pendingState.value=result.state==='NOT_FOUND'?'尚未读取到原请求记录。保留原请求身份，可填写完整原参数核查后恢复。':'原请求尚未取得完整结果。保留原请求身份，继续查询或使用原参数恢复。'}
async function recover(){if(busy.value)return;user.medicalWriting=true;try{await resolvePending()}finally{user.medicalWriting=false}}
async function write(kind:ConnectorOperation,body:unknown,id:string|null,profile:string|null=null){const session=user.medicalSession;if(!session||busy.value||!projectId.value)return;user.medicalWriting=true;try{const original=await prepareConnectorWrite(session,kind,projectId.value,id,body,profile);pending.value=original;pendingBody.value=body;await submitConnectorWrite(session,original,body,controller.value.signal);await resolvePending();if(!pending.value){editOpen.value=false;await loadDirectory(null)}}finally{user.medicalWriting=false}}
async function save(value:ConnectorCreate){await write('CREATE',value,null)}
async function decide(decision:'APPROVED'|'REVOKED'){const value=selected.value;if(!value||!reason.value.trim()||!can('connector.approve'))return;await write('DECIDE',{decision,definition_sha256:value.definition_sha256,expected_revision:value.revision,reason:reason.value.trim()},value.config_revision,value.business_profile?.profile_sha256??null)}
async function verify(){const value=selected.value;if(!value||value.state==='BLOCKED'||!can('connector.configure'))return;await write('VERIFY',{definition_sha256:value.definition_sha256},value.config_revision)}
async function sync(){const value=selected.value;if(!value||!value.connected||!can('connector.sync'))return;await write('SYNC',{definition_sha256:value.definition_sha256,expected_cursor_revision:value.cursor_revision,maximum_items:maximumItems.value},value.config_revision)}
async function resubmit(){const session=user.medicalSession,original=pending.value;if(!session||!original||busy.value)return;const body=pendingBody.value??(original.restore_parameters?original.kind==='DECIDE'?{...original.restore_parameters,reason:restoreReason.value.trim()}:original.restore_parameters:null);if(!body)return;user.medicalWriting=true;try{await submitConnectorWrite(session,original,body,controller.value.signal,true);await resolvePending()}finally{user.medicalWriting=false}}
watch(projectId,()=>{entries.value=[];directoryRead.value=false;nextAfter.value=null;selected.value=null;detailOpen.value=false;history.value=null})
watch(detailTab,()=>{history.value=null;run.value=null})
watch(()=>user.medicalSession,()=>{clear();projectId.value='';if(active.value&&user.medicalSession)void refresh()},{immediate:true})
watch(active,value=>{if(value&&user.medicalSession&&!workspace.value)void refresh()})
onBeforeUnmount(clear)
</script>
