:1px solid #dce3ec}.action-row{display:flex;gap:12px;flex-wrap:wrap;margin:16px 0 24px}.form-note{color:#526279;font-size:12px;line-height:1.8}.el-descriptions{margin:20px 0}.el-drawer pre{white-space:pre-wrap;overflow-wrap:anywhere}.el-drawer .el-alert{margin:20px 0}@media(max-width:1000px){.connection-categories{grid-template-columns:1fr}.enterprise-facts{grid-template-columns:1fr}.connection-categories p{min-height:0}}@media(max-width:650px){.connector-workspace{padding:16px}.workspace-heading,.panel-heading{align-items:flex-start;flex-direction:column}.directory-filters .el-form{flex-wrap:wrap;gap:0}}
</style>
